fn next_power_of_two(n: i64) -> i64 {
    // Handle edge case where n <= 0
    if n < 1 {
        return 1;
    }

    // Step 1: Decrement n
    n = n - 1;

    // Step 2: Propagate the highest set bit to all lower positions
    // We perform shifts of 1, 2, 4, 8, 16, 32 to cover up to 63 bits (since i64 is signed 64-bit)
    // This ensures that if any bit is set, all bits to its right are also set.
    n = n | (n >> 1);
    n = n | (n >> 2);
    n = n | (n >> 4);
    n = n | (n >> 8);
    n = n | (n >> 16);
    n = n | (n >> 32);

    // Step 3: Increment to get the next power of two
    return n + 1;
}

