fn sum_of_primes_upto(n: i64) -> i64 {
    total: i64 = 0;
    k: i64 = 2;
    while k <= n {
        is_p: i64 = 1;
        d: i64 = 2;
        while (d * d) <= k {
            if (k % d) == 0 {
                is_p = 0;
            }
            d = d + 1;
        }
        if is_p == 1 {
            total = total + k;
        }
        k = k + 1;
    }
    return total;
}

